title:
Header
{
  "alg": "HS256",  // 서명 알고리즘
  "typ": "JWT"
}

Payload
{
  "userId": 1,
  "role": "admin",
  "exp": 1704067200  // 만료 시간
}

Signature
HMACSHA256(
  base64(Header) + "." + base64(Payload),
  서버의_비밀키
)

